def collect_directory_files(
    directory: Path,
    source_root: Path,
    files: dict[str, Path],
    tracked_paths: set[str] | None = None,
) -> None:
    with os.scandir(directory) as entries:
        for entry in sorted(entries, key=lambda item: item.name):
            path = Path(entry.path)
            relative_path = path.relative_to(source_root).as_posix()
            if tracked_paths is not None and not any(
                tracked_path == relative_path or tracked_path.startswith(relative_path + "/")
                for tracked_path in tracked_paths
            ):
                continue
            mode = entry.stat(follow_symlinks=False).st_mode
            if entry.name == "__pycache__" and stat.S_ISDIR(mode):
                continue
            if stat.S_ISLNK(mode):
                raise ReleaseError(f"declared input contains a symlink: {path}")
            if stat.S_ISDIR(mode):
                collect_directory_files(path, source_root, files, tracked_paths)
                continue
            if not stat.S_ISREG(mode):
                raise ReleaseError(f"declared input contains a special file: {path}")
            if relative_path in files:
                raise ReleaseError(f"declared inputs overlap at {relative_path}")
            files[relative_path] = path


def collect_files(
    source_root: Path,
    declared_inputs: list[str],
    output_dir: Path | None,
    generated_inputs: list[str] | None = None,
) -> tuple[list[tuple[Path, str]], set[str], set[str]]:
    root = lexical_path(source_root)
    output = lexical_path(output_dir) if output_dir is not None else None
    if output is not None:
        reject_symlink_path(output, require_exists=False)
    tracked_paths: set[str] | None = None
    if root == REPOSITORY_ROOT:
        try:
            tracked_paths = set(run_repository_git(REPOSITORY_ROOT, ["ls-files", "-z"], "indexed source paths").decode("utf-8").split("\0"))
        except UnicodeDecodeError as error:
            raise ReleaseError(f"cannot enumerate Git-indexed source paths: {error}") from error
        tracked_paths.discard("")
    generated_candidates: list[tuple[str, Path]] = []
    for generated_input in generated_inputs or []:
        candidate = resolve_declared_path(root, generated_input)
        if output is not None and is_within(output, candidate):
            raise ReleaseError("output directory must not be inside a generated input")
        generated_candidates.append((generated_input, candidate))
    files: dict[str, Path] = {}
    for declared_input in declared_inputs:
        file_count_before = len(files)
        candidate = resolve_declared_path(root, declared_input)
        if output is not None and is_within(output, candidate):
            raise ReleaseError("output directory must not be inside a declared input")
        mode = os.lstat(candidate).st_mode
        if stat.S_ISREG(mode):
            relative_path = candidate.relative_to(root).as_posix()
            if tracked_paths is not None and relative_path not in tracked_paths:
                raise ReleaseError(f"declared input is not a Git-indexed source file: {declared_input}")
            if relative_path in files:
                raise ReleaseError(f"declared inputs overlap at {relative_path}")
            files[relative_path] = candidate
        else:
            collect_directory_files(candidate, root, files, tracked_paths)
