  principalName: string;
  scope: {
    id: string;
    name: string;
  };
};

export type AuthenticatedConsoleContext = {
  attentionCount: number;
  locale?: string;
  session: AuthenticatedConsoleSession;
};

export type ConsoleSessionResult =
  | { kind: "anonymous" }
  | { kind: "authenticated"; context: AuthenticatedConsoleContext }
  | { kind: "unavailable" };

export type ConsoleSessionPort = {
  readConsoleSession(): Promise<ConsoleSessionResult>;
};
