function flattenMessages(namespaces: Record<string, Record<string, string>>): Map<string, string> {
  return new Map(Object.entries(namespaces).flatMap(([namespace, messages]) =>
    Object.entries(messages).map(([key, message]) => [`${namespace}.${key}`, message]),
  ));
}

function splitPluralKey(key: string) {
  const category = pluralCategories.find((candidate) => key.endsWith(`_${candidate}`));
  return category === undefined ? { baseKey: key } : { baseKey: key.slice(0, -(category.length + 1)), category };
}

function pluralCategoriesFor(locale: ConsoleLocale): readonly string[] {
  return new Intl.PluralRules(locale).resolvedOptions().pluralCategories;
}

function interpolationNames(message: string): string[] {
  return [...message.matchAll(/\{\{(\w+)\}\}/g)].map((match) => match[1]).sort();
}

