def git_output(arguments: list[str], label: str) -> bytes:
    return run_repository_git(REPOSITORY_ROOT, arguments, label)


def reviewed_revision() -> str:
    return git_output(["rev-parse", "HEAD"], "revision").decode("ascii").strip()


def resolve_reviewed_revision(revision: str) -> str:
    resolved_revision = git_output(["rev-parse", "--verify", f"{revision}^{{commit}}"], "revision").decode("ascii").strip()
    if resolved_revision != reviewed_revision():
        raise ReleaseError("reviewed revision must resolve to the checked-out HEAD commit")
    return resolved_revision


def reviewed_tree_identity(revision: str) -> tuple[str, str]:
    tree_sha = git_output(["rev-parse", "--verify", f"{revision}^{{tree}}"], "tree identity").decode("ascii").strip()
    tree_contents = git_output(["cat-file", "tree", revision], "tree contents")
